//! Schema guard and column discovery.
//!
//! The guard compares the upstream `migrations` table with the migrations
//! this build was generated against (`compat/baseline/supported-migrations.txt`,
//! produced by `coolify-port inventory`). Column discovery lets queries adapt
//! to columns added by newer upstream releases without guessing.

use std::collections::{BTreeMap, BTreeSet};

use sqlx::PgPool;

use crate::{DbError, DbResult};

/// Upstream migrations this build supports. Regenerated by the migration engine.
pub const SUPPORTED_MIGRATIONS_FILE: &str =
    include_str!("../../../compat/baseline/supported-migrations.txt");

/// Tables whose columns are discovered at startup.
const INSPECTED_TABLES: &[&str] = &[
    "teams",
    "users",
    "team_user",
    "personal_access_tokens",
    "instance_settings",
    "projects",
    "project_settings",
    "environments",
    "private_keys",
    "server_settings",
    "scheduled_task_executions",
    "scheduled_database_backup_executions",
    "scheduled_volume_backup_executions",
];

pub fn supported_migrations() -> BTreeSet<String> {
    SUPPORTED_MIGRATIONS_FILE
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(str::to_string)
        .collect()
}

#[derive(Debug, Clone, Default)]
pub struct SchemaInfo {
    pub applied: usize,
    /// Applied upstream migrations this build does not know.
    pub unknown: Vec<String>,
    /// Supported migrations missing from the database (older upstream).
    pub missing: Vec<String>,
    /// Table -> columns in ordinal order.
    pub columns: BTreeMap<String, Vec<String>>,
    /// Set when writes must be refused.
    pub read_only_reason: Option<String>,
}

impl SchemaInfo {
    pub fn has_column(&self, table: &str, column: &str) -> bool {
        self.columns
            .get(table)
            .is_some_and(|cols| cols.iter().any(|c| c == column))
    }
}

pub async fn inspect(pool: &PgPool, allow_unknown: bool) -> DbResult<SchemaInfo> {
    let applied: Vec<String> = sqlx::query_scalar("SELECT migration FROM migrations")
        .fetch_all(pool)
        .await
        .map_err(|e| DbError::Schema(format!("cannot read upstream migrations table: {e}")))?;
    let info = evaluate(
        &applied.into_iter().collect(),
        &supported_migrations(),
        allow_unknown,
    );

    let rows: Vec<(String, String)> = sqlx::query_as(
        "SELECT table_name::text, column_name::text FROM information_schema.columns \
         WHERE table_schema = current_schema() AND table_name = ANY($1) \
         ORDER BY table_name, ordinal_position",
    )
    .bind(INSPECTED_TABLES)
    .fetch_all(pool)
    .await?;
    let mut columns: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (t, c) in rows {
        columns.entry(t).or_default().push(c);
    }
    for t in INSPECTED_TABLES {
        if !columns.contains_key(*t) {
            return Err(DbError::Schema(format!("required table `{t}` is missing")));
        }
    }
    Ok(SchemaInfo { columns, ..info })
}

/// Pure decision logic, unit-tested separately from the database.
pub fn evaluate(
    applied: &BTreeSet<String>,
    supported: &BTreeSet<String>,
    allow_unknown: bool,
) -> SchemaInfo {
    let unknown: Vec<String> = applied.difference(supported).cloned().collect();
    let missing: Vec<String> = supported.difference(applied).cloned().collect();
    let read_only_reason = if !unknown.is_empty() && !allow_unknown {
        Some(format!(
            "database has {} upstream migration(s) this coolify-rs build has not been validated against (newest: {}); \
             set COOLIFY_RS_ALLOW_UNKNOWN_SCHEMA=true to override",
            unknown.len(),
            unknown.last().map(String::as_str).unwrap_or("?")
        ))
    } else if !missing.is_empty() {
        Some(format!(
            "database is missing {} upstream migration(s) this build expects (oldest: {}); upgrade upstream first",
            missing.len(),
            missing.first().map(String::as_str).unwrap_or("?")
        ))
    } else {
        None
    };
    SchemaInfo {
        applied: applied.len(),
        unknown,
        missing,
        columns: BTreeMap::new(),
        read_only_reason,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn set(v: &[&str]) -> BTreeSet<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn embedded_list_is_the_main_baseline() {
        let s = supported_migrations();
        assert_eq!(s.len(), 478);
        assert!(s.contains("2026_10_25_115811_add_is_two_factor_required_to_teams_table"));
        assert!(
            s.contains("2026_10_28_124421_keep_dockerfile_healthcheck_for_existing_applications")
        );
        // `bootstrap::MIGRATIONS` only names migrations the guard accepts.
        for m in crate::bootstrap::MIGRATIONS {
            assert!(s.contains(m.name), "{}", m.name);
        }
        assert!(s.contains("2014_10_12_000000_create_users_table"));
    }

    #[test]
    fn guard_decisions() {
        let sup = set(&["a", "b"]);
        assert!(
            evaluate(&set(&["a", "b"]), &sup, false)
                .read_only_reason
                .is_none()
        );
        let newer = evaluate(&set(&["a", "b", "c"]), &sup, false);
        assert_eq!(newer.unknown, vec!["c"]);
        assert!(newer.read_only_reason.is_some());
        assert!(
            evaluate(&set(&["a", "b", "c"]), &sup, true)
                .read_only_reason
                .is_none()
        );
        let older = evaluate(&set(&["a"]), &sup, true);
        assert_eq!(older.missing, vec!["b"]);
        assert!(older.read_only_reason.is_some());
    }
}
